n30898.content:
\begin{definition}
	The fourier transformation is a continuous bijection
	\begin{align*}
		\cS &\to \cS \\
		\phi &\mapsto \hat \phi  = (\xi \mapsto \int_{\R^d} \phi(x) e^{-2\pi i x \xi} \dm x)
	\end{align*}
\end{definition}

n30902.content:
\begin{definition}
	A fundamental solution of $L$ is a distribution $F$ such that $L(F) = \delta$
\end{definition}

n30905.content:
